1	/* P-D1 / H5 probe: load-use-as-pointer kernel mirroring core 179's
2	 * __per_cpu_offset[i] -> rq dereference failure chain (MICROARCH_SUPPLEMENT §2.2).
3	 *
4	 * Architecture of the failure (from the vmcore forensics):
5	 *   1. a load of a "per-cpu offset array" element returns a STALE value from
6	 *      the array HEAD, byte-lane-skewed (rol_k(slot[0])); truth is intact.
7	 *   2. that skewed value is added to a base pointer -> bogus pointer.
8	 *   3. dereferencing the bogus pointer -> translation fault (kernel: Oops).
9	 *
10	 * This probe emulates steps 1-3 in user space: it keeps an array of pointers
11	 * (analog of __per_cpu_offset[]) and dereferences the loaded entry. Under
12	 * CHAOSLSQFwd structuralFault=byte_lane_skew, the loaded pointer is a byte-
13	 * rotated form of the array-head entry. We detect SDC by comparing the
14	 * dereferenced value against the expected (golden) value, and we detect
15	 * pointer corruption by checking the loaded pointer is canonical & in-range.
16	 *
17	 * Pure libc, no main deps; static link for gem5 SE mode. Exits 0 on pass,
18	 * 1 on SDC, 2 on setup error. The "fails" counter separates:
19	 *   - PTR_CORRUPT: loaded pointer itself is wrong (the D1 signature)
20	 *   - VAL_MISMATCH: dereferenced value mismatches golden
21	 *
22	 * Note: under byte_lane_skew the loaded pointer will usually be non-canonical
23	 * (bits shifted), so PTR_CORRUPT fires and the deref is skipped (mimicking
24	 * the kernel Oops rather than SIGSEGV-ing the sim).
25	 */
26	#include <stdint.h>
27	#include <stdlib.h>
28	#include <stdio.h>
29	#include <string.h>
30	
31	#define NPTR 256          /* analog of __per_cpu_offset[0..191] */
32	#define TARGET_IDX 146    /* the slot the kernel crashed loading (15:58) */
33	
34	static uint64_t rng_state = 0x123456789abcdef0ULL;
35	static inline uint64_t xorshift64(void) {
36	    uint64_t x = rng_state;
37	    x ^= x << 13; x ^= x >> 7; x ^= x << 17;
38	    rng_state = x; return x;
39	}
40	
41	/* Each "pointer slot" points to a 64-bit target whose golden value we know. */
42	int main(int argc, char **argv) {
43	    long iters = (argc > 1) ? atol(argv[1]) : 1000;
44	    uint64_t *slots = (uint64_t*)malloc(NPTR * sizeof(uint64_t)); /* ptr array */
45	    uint64_t *targets = (uint64_t*)malloc(NPTR * sizeof(uint64_t)); /* pointees */
46	    if (!slots || !targets) return 2;
47	
48	    /* init: each slot[j] = &targets[j]; each target[j] = golden(j). */
49	    for (int j = 0; j < NPTR; j++) {
50	        targets[j] = 0x1000ULL * (j + 1);     /* golden: distinct per slot */
51	        slots[j] = (uint64_t)&targets[j];
52	    }
53	    /* Immutable golden truth captured ONCE, never written again — the bug fix.
54	     * The prior version re-read slots[TARGET_IDX] as "truth" right after the
55	     * reload, but that re-read can ITSELF be corrupted (same defect path),
56	     * yielding xor==0 while the check still fires (truth moved with loaded).
57	     * Using a const stack copy taken before any faulting load breaks that
58	     * circular dependency. */
59	    const uint64_t golden_ptr = (uint64_t)&targets[TARGET_IDX];
60	    const uint64_t golden_val = targets[TARGET_IDX];
61	
62	    long ptr_corrupt = 0, val_mismatch = 0;
63	    for (long it = 0; it < iters; it++) {
64	        if ((it & 63) == 0) { rng_state = 0x9E3779B97F4A7C15ULL * (it + 1); }
65	        /* Method2-style store-then-reload so the checked load travels the
66	         * store->load FORWARDING path (the CHAOSLSQFwd injection site). The
67	         * kernel's __per_cpu_offset is .data (no pending store), but the
68	         * D1 *defect* sits on the load-return path that store-forwarding also
69	         * uses; method2/v3 localized the defect precisely on this path. So to
70	         * exercise the injector we store-then-reload the slot under test. */
71	        slots[TARGET_IDX] = golden_ptr;                       /* (re)store truth */
72	        volatile uint64_t loaded = slots[TARGET_IDX];          /* reload = forward */
73	        /* compiler barrier: ensure `loaded` is materialized before the check so
74	         * the comparison uses the actually-forwarded (possibly-corrupted) value,
75	         * not a re-issue. */
76	        asm volatile("" ::: "memory");
77	        uint64_t p = loaded;
78	
79	        /* PTR_CORRUPT detection: compare against the IMMUTABLE golden_ptr, not
80	         * a re-read of slots[]. A byte-lane skew makes loaded != golden_ptr.
81	         * NOTE: we intentionally do NOT print xor/loaded/truth here — under
82	         * heavy structural injection the compiler's stack-spill reloads can
83	         * themselves be skewed, producing misleading xor==0 rows. The
84	         * DECISIVE signal is the downstream deref page-fault (the kernel-style
85	         * Oops), which is unaffected by detection-path noise. We count
86	         * ptr_corrupt but only the crash/val_mismatch are reported as results. */
87	        if (p != golden_ptr) {
88	            ptr_corrupt++;
89	            continue;  /* skip deref — would SIGSEGV/Oops, as the kernel did */
90	        }
91	
92	        /* deref (analog of rq = *(ptr+base)). */
93	        uint64_t got = *(uint64_t*)p;
94	        if (got != golden_val) {
95	            val_mismatch++;
96	            if (val_mismatch <= 8)
97	                fprintf(stderr, "VAL_MISMATCH it=%ld got=%016lx golden=%016lx\n",
98	                        it, got, golden_val);
99	        }
100	    }
101	
102	    long fails = ptr_corrupt + val_mismatch;
103	    printf("iters=%ld ptr_corrupt=%ld val_mismatch=%ld fails=%ld\n",
104	           iters, ptr_corrupt, val_mismatch, fails);
105	    free(slots); free(targets);
106	    return fails ? 1 : 0;
107	}
